    "ward.qm-no-due-times": "এই সময়ের মধ্যে দেওয়া {given} টি ডোজের কোনোটিতেই নির্ধারিত সময় রেকর্ড করা নেই, তাই বিলম্ব গণনা করা যাচ্ছে না। 2026-09-07 এর আগে লেখা অ্যাডমিনিস্ট্রেশন রেকর্ডে dueAt নেই।",
    "ward.qm-no-allergy-status-record": "WardSynQ \"জিজ্ঞাসা করা হয়েছে, এবং কোনো এলার্জি নেই\" রেকর্ড করতে পারে না, তাই কোনো এলার্জি রেকর্ড না থাকা রোগীকে এমন রোগীর থেকে আলাদা করা যায় না যাকে কেউ জিজ্ঞাসা করেনি। এখানকার যেকোনো হার এমন ওয়ার্ডের ভালো ডকুমেন্টেশন রিপোর্ট করবে যা কখনোই জিজ্ঞাসা করে না। এর জন্য একটি কোনো জানা এলার্জি নেই এমন রেকর্ড প্রয়োজন, গণনা নয়।",
    "ward.qm-no-antibiotic-list": "অ্যান্টিবায়োটিক তালিকা কনফিগার করা হয়নি। এই হাসপাতাল যে ওষুধের নাম বা কোড গণনা করে তাতে প্রতিষ্ঠানের wardsynq.antibiotics সেট করুন।",
    "ward.qm-no-beds-configured": "এই হাসপাতালের জন্য কোনো বেড কনফিগার করা হয়নি (wardsynq.beds), তাই কোনো খালি বেড-ডে হর (denominator) নেই।",
