    "ward.gst-pkg-room-carved": "এই প্যাকেজে দৈনিক Rs 5,000-এর ওপরে {days} টি room day(s) অন্তর্ভুক্ত আছে। প্যাকেজের Rs {taxable} পরিমাণ অর্থ Room charges হিসেবে দেখানো হয়েছে এবং এতে 5% ট্যাক্স ধরা হয়েছে। প্যাকেজের অবশিষ্ট অংশ ট্যাক্সমুক্ত। Valuation method: {methodName}।",
    "ward.gst-pkg-room-capped": "এই স্টের জন্য Room tariff প্যাকেজের মূল্যের চেয়ে বেশি। GST-র জন্য পুরো প্যাকেজ মূল্যকে Room charges হিসেবে গণ্য করা হয়েছে। ইস্যু করার আগে প্যাকেজ এবং Room category পরীক্ষা করুন।",
    "ward.gst-pkg-room-fallback": "GST সেটিংসের নির্বাচিত মূল্যায়ণ এই প্যাকেজের জন্য ব্যবহার করা সম্ভব হয়নি, তাই প্রকাশিত রুম শুল্ক ব্যবহার করা হয়েছে।",
    "ward.gst-pkg-unrecoverable": "এই প্যাকেজের Room charges-এর ওপর Rs {tax} টাকার GST হাসপাতালকে প্রদান করতে হবে কারণ Payer-এর প্যাকেজ রেট অতিরিক্ত GST অনুমোদন করে না।",
    "ward.gst-pkg-tds": "এই স্কিমটিকে নোটিফাইড GST TDS deductor হিসেবে চিহ্নিত করা হয়েছে: এটি ট্যাক্সযুক্ত Room charges-এর ওপর GST TDS কাটতে পারে (Section 51)। এর 10 শতাংশ claim deduction হলো Income tax TDS, GST নয়।",
    "ward.gst-room-why": "GST 5% প্রযোজ্য কারণ এই রুমটি ICU, CCU, ICCU বা NICU নয় এবং এর চার্জ প্রতিদিন Rs 5,000-এর বেশি (Notification 11/2017-Central Tax (Rate), entry 31A)।",
    "ward.gst-exempt-footnote": "Clinical establishment দ্বারা প্রদত্ত Health care services GST থেকে মুক্ত (Notification 12/2017-Central Tax (Rate), entry 74)। Admitted patient-কে সরবরাহ করা ওষুধ, Implants, Consumables এবং খাবার এই সেবারই অংশ।",
    "ward.e-invoicing-no-turnover": "E-invoicing চালু নেই: হাসপাতালের মোট turnover, ট্যাক্সমুক্ত সরবরাহসহ, Admin, Price list, GST settings-এ এন্ট্রি করা হয়নি। এই বিলের কোনো কিছুই রিপোর্ট করা হয়নি।",
    "ward.e-invoice-exempt-only": "E-invoicing-এর জন্য ট্যাক্সমুক্ত সরবরাহ রিপোর্ট করা হয় না। এই Bill of Supply-এর কোনো IRN নেই।",
    "ward.e-invoice-mixed-b2b": "নিবন্ধিত Payer-এর জন্য এই বিলে ট্যাক্সযুক্ত এবং ট্যাক্সমুক্ত উভয় চার্জ রয়েছে। এটি একটি Tax Invoice (E-invoicing-এর জন্য রিপোর্ট করা) এবং একটি পৃথক Bill of Supply হিসেবে ইস্যু করা হবে।",
    "ward.gst-note-late": "Section 34-এর সময়সীমা অতিক্রান্ত: এই নোটটি GST ছাড়াই ইস্যু করা হয়েছে।",
    "ward.gst-note-refunded": "এই নোটের সাথে রোগী/পেশেন্টকে GST ফেরত দেওয়া হয়েছে {ref}।",
    "ward.gst-note-itc": "ক্রেতা দ্বারা Input tax credit reversal নিশ্চিত করা হয়েছে: {ref}।",
    "ward.gst-note-financial": "এই নোটে কোনো GST নেই: এটি একটি Financial note, E-invoicing-এর জন্য রিপোর্ট করা হয় না।",
    "ward.gst-room-tariff-missing": "এই প্যাকেজটি {roomCategoryName}-এর room days কভার করে, যার কোনো দৈনিক Room tariff Price list-এ নেই। GST হিসাব করা যাচ্ছে না। এই বিল ইস্যু করার আগে Tariff যোগ করুন।",
    "ward.gst-rate-missing": "এই আইটেমগুলি করযোগ্য এবং মূল্যের তালিকায় কোনো GST হার নেই, তাই কোনো বিল তৈরি করা হয়নি: {codes}। একজন অ্যাডমিনিস্ট্রেটর প্রতিটি হার সেট করেন; কোনোটিই আনুমানিক ধরে নেওয়া হয় না।",
    "ward.gst-note-ask-title": "এই ক্রেডিট নোটে GST",
    "ward.gst-note-ask-registered": "এই ক্রেডিট নোটে GST হাসপাতালের কর কমায় কেবল তখনই যখন {payerName} মেলানো ইনপুট ট্যাক্স ক্রেডিট রিভার্স করে। তাদের নিশ্চিতকরণ রেকর্ড করুন।",
    "ward.gst-note-ask-patient": "এই ক্রেডিট নোটে GST হাসপাতালের কর কমায় কেবল যদি রোগীর কাছে GST রিফান্ড করা হয়। এই নোটের সাথে Rs {gst} GST রিফান্ড করুন, অথবা এটি GST ছাড়া ইস্যু করুন।",
