    "site.abdm.intro2": "এই হাসপাতাল পরবর্তীতে ABDM থেকে যে রেকর্ডগুলো পাবে সেগুলো পেশেন্টের চার্টে থাকবে, যা ওই সম্মতির অধীনে প্রাপ্ত হিসেবে চিহ্নিত থাকবে, এমনকি পেশেন্ট পরবর্তীতে সম্মতি প্রত্যাহার করে নিলেও।",
