    "site.admin.staff.roleNote.admin": "সম্পূর্ণ টেকনিক্যাল অ্যাডমিনিস্ট্রেশন: স্টাফ, ওয়ার্ড, বেড, ডিপার্টমেন্ট, রুম, বিলিং কনফিগ। ক্লিনিক্যাল প্রটোকল সাইন-অফ নয়।",
    "site.admin.staff.roleNote.doctor": "সম্পূর্ণ ক্লিনিকাল ওয়ার্কফ্লো: কিউ, EMR, অর্ডার, প্রেসক্রিপশন, নিজস্ব রোগী।",
    "site.admin.staff.roleNote.nurse": "ডেস্কে কিউ পরিচালনা করেন, ভাইটাল রেকর্ড করেন, বেডসাইডে ওষুধ দেন (eMAR)। প্রেসক্রাইব করার অধিকার নেই।",
    "site.admin.staff.roleNote.reception": "রোগী রেজিস্ট্রেশন ও চেক-ইন করেন, ডাক্তারের কাছে অ্যাসাইন করেন। চার্ট পড়তে পারেন, এডিট করতে পারেন না।",
    "site.admin.staff.roleNote.pharmacy": "মেডিকেশন অর্ডার পড়েন ও ডিসপেন্স করেন, চার্টের সাথে অর্ডার ভেরিফাই করেন। কনসালটেশন নোট লিখতে পারেন না।",
    "site.admin.staff.roleNote.lab": "অর্ডার করা টেস্ট দেখেন এবং রেজাল্ট রিলিজ করেন। চার্টের অন্য কোনো অ্যাক্সেস নেই।",
    "site.admin.staff.roleNote.billing": "চার্জ, ইনভয়েস এবং ক্লেইম পড়েন। পেমেন্ট নিতে পারেন না (এর জন্য Cashier দেখুন)।",
    "site.admin.staff.roleNote.him": "রিলিজ-অফ-ইনফরমেশন রিকোয়েস্ট সিদ্ধান্ত ও রেকর্ড করার জন্য চার্ট পড়েন।",
    "site.admin.staff.roleNote.bloodBank": "শুধু ক্রস ম্যাচিং করেন, ট্রান্সফিউশন ইস্যু ও অ্যাডমিনিস্টার করেন।",
    "site.admin.staff.roleNote.radiographer": "ইমেজিং স্টাডি অ্যাকোয়ার করেন। চার্ট পড়তে পারেন, রিপোর্ট ফাইল করতে বা স্টাডি প্রোটোকল করতে পারেন না।",
    "site.admin.staff.roleNote.radiologist": "ইমেজিং স্টাডি প্রোটোকল ও রিপোর্ট করেন (ল্যাব রেজাল্ট রিলিজের মতো একই অথরিটি)। চার্টে অন্য কোনো রাইট অ্যাক্সেস নেই।",
    "site.admin.staff.roleNote.obstetrician": "একজন ডাক্তার যিনি PCPNDT Form F এবং MTP রেজিস্টারও পরিচালনা করেন।",
    "site.admin.staff.roleNote.publicHealth": "পাবলিক হেলথ নোডাল অফিসার: পেশেন্ট চার্ট পড়েন এবং নোটিফায়েবল ডিজিজ রেজিস্টার ও সাপ্তাহিক IHIP এক্সপোর্ট পরিচালনা করেন।",
    "site.admin.staff.roleNote.supervisor": "OPD কিউ পরিচালনা করেন এবং পেশেন্ট চার্ট পড়েন। তাঁর আওতাধীন বিভাগগুলির স্টোর ইনডেন্ট অনুমোদন করেন।",
    "site.admin.staff.roleNote.storeKeeper": "জেনারেল স্টোর পরিচালনা করেন: আইটেম, স্টোর লোকেশন, অনুমোদিত ইনডেন্ট ইস্যু করা, রিসিভ করা এবং অর্ডার করা। চার্ট অ্যাক্সেস নেই।",
    "site.admin.staff.roleNote.biomedicalEngineer": "অ্যাসেট রেজিস্টার, প্রিভেন্টিভ মেনটেন্যান্স, ক্যালিব্রেশন এবং জব কার্ড পরিচালনা করেন। চার্ট অ্যাক্সেস নেই।",
