    "site.admin.hospital.printLang.intro": "ইংরেজি প্রিন্টটি সবসময় সম্পূর্ণ এবং এটিই চূড়ান্ত। দ্বিতীয় ভাষাটি এর পাশে প্রিন্ট করা হয়, যা অনুবাদ হিসেবে চিহ্নিত থাকে এবং এতে কেবল হেডিং, লেবেল এবং প্রিসক্রাইবার নির্দিষ্ট তালিকা থেকে বেছে নেওয়া রোগীর নির্দেশাবলী কভার করে। ওষুধের নাম, ডোজ, ফ্রিকোয়েন্সি, ডায়াগনোসিস, রেজাল্ট এবং টাইপ করা যেকোনো কিছু কেবল ইংরেজিতেই প্রিন্ট হবে। যেসব অনুবাদ এখনও লেখা হয়নি সেগুলো ইংরেজিতে দেখাবে।",
