    "site.legal.intro": "WardSynQ দ্বারা প্রয়োগ করা প্রতিটি প্রয়োজনীয়তা, তার উৎস, স্ট্যাটাস এবং তারিখ সহ। কোন প্রয়োজনীয়তা চ্যালেঞ্জের মুখে থাকলেও তা বলবৎ থাকবে, যতক্ষণ না কোন আদালত এতে স্থগিতাদেশ দিচ্ছেন। State/UT-এর মান কেবল তাদের উৎসের সাথেই পরিবর্তিত হয়; আপনার State/UT-এর জন্য নির্ধারণ না করা মানগুলি এই হাসপাতালের কনফিগার করার বিষয়।",
