    "site.gov.req.clockSpdi": "SPDI Rules 2011-এর অধীনে উত্তর দেওয়ার সময় (সূচনার পর থেকে প্রাপ্ত অনুরোধের জন্য DPDP সময় প্রযোজ্য):",
    "site.gov.req.contact": "উত্তরে যে যোগাযোগের নাম উল্লেখ করা হয়েছে:",
    "site.gov.req.copiesNote": "রোগী, একজন অনুমোদিত অ্যাটেনডেন্ট বা আইনি কর্তৃপক্ষের দ্বারা মেডিকেল রেকর্ডের কপির অনুরোধ রোগীর চার্টে তথ্যের প্রকাশ হিসেবে রেকর্ড করা হয়, যেখানে এর 72-ঘণ্টার ঘড়ি চলে (IMC Regulations 2002 reg 1.3.2)।",
    "site.gov.clocks.reasonNeeded": "72 ঘণ্টার বেশি সময়ের জন্য অন্তত 10 টি অক্ষরের একটি কারণ প্রয়োজন; এটি ছাড়া 72-ঘণ্টার টার্গেট ব্যবহার করা হয়।",
    "site.gov.ret.unreadable": "আইন অনুযায়ী হাসপাতালের কী রাখা প্রয়োজন তা নির্ধারণ করা যায়নি। এর অর্থ এই নয় যে কিছুই রাখা হয়নি।",
