    "site.gov.br.extendedTo": "Board-এর নতুন তারিখ (শুধুমাত্র সময় বৃদ্ধি)",
    "site.gov.br.text2": "বিস্তারিত: মূল্যায়ন, CERT-In বা Board-এর রেফারেন্স, Board-কে প্রথমে কী বলা হয়েছিল, রোগীদের কীভাবে জানানো হয়েছিল, পদক্ষেপ, কেন এটি লঙ্ঘন নয়, অথবা সমাপনী সারাংশ",
    "site.gov.br.piTitle": "রোগীদের কী বলা হয়েছিল (DPDP Rules 2025 r.7(1), পাঁচটিই)",
    "site.gov.br.bhTitle": "Board-এর কাছে বিস্তারিত রিপোর্ট (DPDP Rules 2025 r.7(2)(b))",
    "site.gov.br.law2": "সাইবার নিরাপত্তা সংক্রান্ত কোনো ঘটনা, যার মধ্যে ডেটা লঙ্ঘনও অন্তর্ভুক্ত, তা লক্ষ্য করার 6 ঘণ্টার মধ্যে CERT-In-কে রিপোর্ট করুন (এখন কার্যকর)। DPDP শুরুর পর থেকে Data Protection Board-কে দেরি না করে জানাতে হবে এবং অবগতির 72 ঘণ্টার মধ্যে বিস্তারিত রিপোর্ট পাঠাতে হবে, এবং প্রভাবিত প্রতিটি রোগীকে দেরি না করে জানাতে হবে। 'not notifiable' বা বিজ্ঞপ্তিযোগ্য নয় এমন কোনো অবস্থা নেই: একটি রেকর্ড কেবল তখনই প্রত্যাহার করা হয় যদি তা ব্যক্তিগত ডেটা লঙ্ঘন না হয়, যা দ্বিতীয় কোনো ব্যক্তি দ্বারা নিশ্চিত করা হয়েছে। এখানে লঙ্ঘিত ব্যক্তিগত ডেটা নিজে লিখবেন না।",
    "site.gov.br.awareAt": "হাসপাতাল জানতে পেরেছে (যদি পরে হয়)",
