    "site.gov.nt.p.board": "Data Protection Board-এর কাছে কীভাবে অভিযোগ করবেন (DPDP শুরুর পর থেকে প্রয়োজনীয়)",
    "site.gov.nt.s5b": "নোটিশ প্রকাশের আগে নিচের প্রতিটি অংশ প্রয়োজন: একটি একটি করে ডেটা আইটেম, উদ্দেশ্য, প্রত্যাহার, অধিকার, প্রাপক এবং হাসপাতালের নাম ও ঠিকানা (DPDP Rules 2025 r.3; SPDI Rules 2011 r.5(3)), এবং Data Protection Officer বা Grievance Officer-এর যোগাযোগ। এটি ইংরেজিতে বা অষ্টম তফসিলের কোনো ভাষায় লিখুন। পুনরায় প্রকাশ করলে একটি নতুন সংস্করণ তৈরি হয়; রোগীরা একটি সংস্করণ স্বীকার করেন। DPDP শুরুর পর থেকে, তার আগে নোটিশ দেওয়া রোগীদের একটি নতুন নোটিশ প্রয়োজন (s.5(2))।",
    "site.gov.nt.textOptional": "নোটিশে বলা অন্য যেকোনো কিছু (ঐচ্ছিক)",
    "site.gov.nt.dpo2": "Data Protection Officer বা Grievance Officer-এর যোগাযোগ (প্রকাশিত)",
    "site.gov.nt.oldVersion": "আইটেমভিত্তিক অংশগুলো প্রয়োজন হওয়ার আগে এই সংস্করণটি প্রকাশিত হয়েছিল। প্রতিটি অংশসহ এটি পুনরায় প্রকাশ করুন।",
