    "site.gov.ret.title": "রেকর্ড কতদিন সংরক্ষণ করা হবে",
    "site.gov.ret.intro2": "স্বয়ংক্রিয়ভাবে কোনো কিছু মোছা হয় না। প্রতিটি শ্রেণি দেখায় কী এটিকে ধরে রাখে: একটি আইন, যার বিধানের সাথে উল্লেখ করা হয়েছে, অথবা হাসপাতালের রিটেনশন পলিসি, যা কোনো আইনি বাধ্যবাধকতা নয়। একটি লিগ্যাল হোল্ড বিষয়টি নিষ্পত্তি না হওয়া পর্যন্ত সবকিছু ধরে রাখে। আইনের দ্বারা নির্ধারিত সময়ের মধ্যে নথি মোছা প্রত্যাখ্যান করা হয়; কেবল পলিসি দ্বারা নির্ধারিত সময়ের মধ্যে মুছতে DPO বা মেডিকেল রেকর্ডস অফিসারের নিশ্চিতকরণ প্রয়োজন।",
