    "site.gov.ret.decIntro": "এই রেকর্ডগুলি কোনো আইন দ্বারা সংরক্ষিত নয়। প্রতিটির জন্য, এটি সংরক্ষণ করুন এবং উদ্দেশ্য বা প্রয়োজনীয়তা লিখুন, অথবা মুছে ফেলুন। WardSynQ নিজেই একটি ক্লিনিকাল রেকর্ড মুছে ফেলে না: মেডিকেল রেকর্ড অফিসার এটি ধ্বংস করেন বা ডি-আইডেন্টিফাই করেন, এবং ধ্বংসের রেকর্ড রেফারেন্স দিয়ে অনুরোধটি সম্পন্ন হয়।",
