    "site.gov.ret.dpdpNow": "DPDP প্রযোজ্য: আইন দ্বারা নির্ধারিত সময়সীমা মুছে ফেলা প্রতিরোধ করে; শুধুমাত্র হাসপাতালের নীতি দ্বারা নির্ধারিত সময়সীমা নথিভুক্ত সিদ্ধান্তের জন্য DPO-র কাছে যায়।",
    "site.gov.ret.dpdpLater": "DPDP শুরু না হওয়া পর্যন্ত মুছে ফেলা নিচের প্রতিটি class রক্ষা করে। তারপর থেকে, শুধুমাত্র আইন দ্বারা নির্ধারিত সময়সীমা মুছে ফেলা প্রতিরোধ করে; শুধুমাত্র হাসপাতালের নীতি দ্বারা নির্ধারিত সময়সীমা নথিভুক্ত সিদ্ধান্তের জন্য DPO-র কাছে যায়।",
