    "site.admin.gst.roomValuationWhy": "প্যাকেজের ভেতরে কোনো রুমের মূল্য কীভাবে নির্ধারণ করতে হবে সে বিষয়ে কোনো নিয়ম, সার্কুলার বা রুলিং নেই; প্রকাশিত ট্যারিফ, যা প্যাকেজের মূল্যে সীমাবদ্ধ, তা কম ট্যাক্স দেওয়া এড়ায়।",
