    "site.admin.gst.intro": "যেখানে আইন চূড়ান্ত নয়, প্রতিটি সেটিং সবচেয়ে নিরাপদ ব্যাখ্যা দিয়ে শুরু হয়। ডিফল্ট ব্যতিরেকে অন্য কোনো পছন্দ বেছে নিতে আপনার চার্টার্ড অ্যাকাউন্ট্যান্টের লিখিত মতামত প্রয়োজন। প্রতিটি পরিবর্তন কারণসহ রেকর্ড করা হয়।",
    "site.admin.gst.tds": "বিজ্ঞাপিত GST TDS কর্তনকারী হিসেবে নিশ্চিত হওয়া স্কিমসমূহ",
    "site.admin.gst.tdsWhy": "GST TDS (Section 51) কেবল একটি চুক্তির অধীনে Rs 2.5 লাখের ওপরের করযোগ্য সরবরাহের ক্ষেত্রে প্রযোজ্য, এবং একটি স্কিম এজেন্সি বিজ্ঞাপিত কর্তনকারী কিনা তা অনিশ্চিত; স্কিমের 10 শতাংশ ক্লেম কর্তন হলো ইনকাম ট্যাক্স TDS, GST নয়।",
    "site.admin.gst.turnover": "2017-18 থেকে যেকোনো আর্থিক বছরে সর্বোচ্চ মোট টার্নওভার, রুপিতে, অব্যাহতিপ্রাপ্ত সরবরাহ অন্তর্ভুক্ত",
    "site.admin.gst.turnoverWhy": "মোট টার্নওভারের মধ্যে অব্যাহতিপ্রাপ্ত সরবরাহ অন্তর্ভুক্ত (Section 2(6))। Rs 5 কোটির ওপরে E-invoicing প্রযোজ্য; কোনো সংখ্যা ইনপুট না করা পর্যন্ত কিছুই রিপোর্ট করা হয় না। Bill of Supply কখনোই রিপোর্ট করা হয় না।",
