    "site.support.miss.inquest": "মেডিকো-লিগ্যাল কেসে রেকর্ড করা ইনকোয়েস্ট বা ম্যাজিস্ট্রেট তদন্তের কাগজপত্র (BNSS ss.194, 196)",
    "site.admin.gst.recipientPerContract": "GST গ্রহীতা (Section 2(93) CGST Act) Integrations, Payers-এর অধীনে প্রতিটি payer contract-এ নির্ধারিত হয় কে সেই চুক্তির অধীনে অর্থ প্রদানে বাধ্য তার ভিত্তিতে, কে টাকা স্থানান্তর করছে তার ভিত্তিতে নয়। Insurers এবং TPAs ডিফল্টভাবে রোগীর জন্য নির্ধারিত হয়; সরকার দ্বারা পরিচালিত প্রকল্প এবং Corporate-গুলি নির্ধারিত থাকে না, এবং আপনি নির্বাচন না করা পর্যন্ত সতর্কবার্তা সহ রোগীর নামে বিল করা হয়।",
    "site.admin.gst.recipientLegacy": "আপনার পূর্ববর্তী হাসপাতাল-ব্যাপী সেটিংস insurer, TPA বা স্কিমকে GST গ্রহীতা করেছিল। প্রতিটি চুক্তিতে নিজস্ব নির্ধারণ না থাকা পর্যন্ত, নিচের চার্টার্ড অ্যাকাউন্ট্যান্টের মতামতের ভিত্তিতে এটি কেবল সেইসব payer contracts-এর জন্য ব্যবহৃত হয়।",
