    "site.admin.fml.intro": "এই হাসপাতালে কী স্টক আছে এবং কী সীমাবদ্ধ করা আছে। তালিকায় না থাকা কোনো ওষুধ অর্ডারে ফ্ল্যাগ করা হয়, কিন্তু কখনোই ব্লক করা হয় না; সীমাবদ্ধ ওষুধটি অনুমোদন বা স্পেশাল্টি উল্লেখ না করা পর্যন্ত ব্লক থাকে। রিটায়ার্ড এন্ট্রিগুলি তালিকায় থেকে যায় এবং কোনো অর্ডারের সাথে মেলে না। WardSynQ-এর সাথে কিছুই আসে না: এই তালিকাটি হাসপাতালের নিজস্ব।",
