    "site.admin.ccs.critical.title": "Critical সীমা",
    "site.admin.ccs.critical.intro": "যে কম বা বেশি ভ্যালু স্পর্শ করলে বা অতিক্রম করলে ল্যাব ফলাফল একটি critical ফলাফল লুপ তৈরি করে। ল্যাবের নিজস্ব critical ফ্ল্যাগও সবসময় গণ্য হয়। এখানে তালিকাভুক্ত নয় এমন কোনো অ্যানালাইটের ক্ষেত্রে নিচে দেখানো বিল্ট-ইন অ্যাডাল্ট ডিফল্ট প্রযোজ্য হবে।",
    "site.admin.ccs.critical.empty": "এই হাসপাতালের জন্য কোনো critical সীমা সেভ করা নেই। সীমা সেভ না করা পর্যন্ত নিচের বিল্ট-ইন অ্যাডাল্ট ডিফল্ট প্রযোজ্য হবে।",
    "site.admin.ccs.delta.title": "Delta চেক সীমা",
    "site.admin.ccs.delta.intro": "স্যাম্পল আইডেন্টিটি চেকের জন্য কোনো রেজাল্ট ফ্ল্যাগ করার আগে, পেশেন্টের পূর্ববর্তী রেজাল্ট থেকে সর্বোচ্চ পরিবর্তন, রেজাল্টের নিজস্ব ইউনিটে একটি মান বা শতাংশ হিসাবে। কোনো রেজাল্ট কখনোই আটকে রাখা হয় না। বিভিন্ন ইউনিটের রেজাল্ট তুলনা করা হয় না। অন্য কোনো সময়সীমা দেওয়া না থাকলে পূর্ববর্তী রেজাল্টটি 72 ঘণ্টার জন্য গণ্য হবে।",
    "site.admin.ccs.delta.empty": "কোনো delta সীমা সেভ করা নেই। ফলাফল delta চেক করা হয় না, এবং প্রতিটি ফলাফলে তা উল্লেখ থাকে।",
    "site.admin.ccs.auto.title": "অটোভেরিফিকেশন",
    "site.admin.ccs.auto.intro": "যে টেস্টের ফলাফল সংখ্যাসূচক, নিজস্ব রেফারেন্স রেঞ্জের মধ্যে, ল্যাব দ্বারা critical ফ্ল্যাগ করা নয় এবং কোনো delta লঙ্ঘন নেই, সেগুলি ম্যানুয়াল রিভিউ ছাড়াই রিলিজ করা যেতে পারে। অন্য সমস্ত কিছু পরীক্ষা করে দেখা হয়।",
    "site.admin.ccs.auto.empty": "Autoverification কনফিগার করা নেই। প্রতিটি ফলাফল ম্যানুয়ালি দেখা হয়।",
    "site.admin.ccs.mar.title": "মেডিসিন রাউন্ডের সময়সূচী",
    "site.admin.ccs.mar.intro": "একটি নির্দিষ্ট ফ্রিকুয়েন্সির জন্য নির্ধারিত সময়, 24 ঘণ্টার ঘড়ি অনুযায়ী, সারা দিনের ক্রমানুসারে। TDS এবং QID সময়গুলো 1-0-1 এবং 1-0-0-1 সংকেতগুলোকেও নির্দেশ করে। এখানে তালিকাভুক্ত নয় এমন ফ্রিকুয়েন্সি নিচে দেখানো বিল্ট-ইন রাউন্ড ব্যবহার করে।",
    "site.admin.ccs.mar.empty": "মেডিসিন রাউন্ডের কোনো সময় সংরক্ষণ করা হয়নি। সময় সংরক্ষণ না হওয়া পর্যন্ত নিচের বিল্ট-ইন রাউন্ড কার্যকর থাকবে।",
    "site.admin.ccs.notes.title": "নোট টেমপ্লেট",
    "site.admin.ccs.notes.intro": "এই হাসপাতালের ক্লিনিক্যাল নোটের শিরোনামসমূহ। একটি সেকশনে একটি প্রশ্ন করা হয় এবং এটিতে কখনো ডিফল্ট টেক্সট থাকে না। প্রতি লাইনে একটি সেকশন: key | title | question | required। বিল্ট-ইন নোটের id সহ একটি টেমপ্লেট সেটিকে প্রতিস্থাপন করে।",
    "site.admin.ccs.notes.empty": "কোনো নোট টেমপ্লেট সংরক্ষণ করা হয়নি। টেমপ্লেট সংরক্ষণ না হওয়া পর্যন্ত বিল্ট-ইন নোটগুলো ব্যবহারযোগ্য থাকবে।",
