    "site.admin.orderBackfill.intro": "এই হাসপাতাল আপডেট হওয়ার আগের ইনভেস্টিগেশন অর্ডারগুলি সম্পূর্ণ বলে চিহ্নিত করা হয়নি, তাই ল্যাবরেটরি এবং রেডিওলজির তালিকায় সেগুলি এখনও বাকি কাজ হিসেবে দেখাচ্ছে। চেক করলে অর্ডারগুলি শুধু পড়া হবে, কিছু লেখা হবে না। ক্লোজ করলে কেবল সেই অর্ডারগুলি চিহ্ন করা হবে যেগুলির ফলাফল ইতিমধ্যেই চার্টে আছে; যে অর্ডারের ফলাফল নেই, যে ইমেজিং স্টাডির কেবল প্রাথমিক রিপোর্ট আছে, এবং অন্য সিস্টেমের অধীনস্থ অর্ডারগুলি অপরিবর্তিত রাখা হবে।",
